refs.extend([dict(id='cycles2025',title='Packing Short Cycles',authors='Matthias Bentert; Fedor V. Fomin; Petr A. Golovach; Tuukka Korhonen; William Lochet; Fahad Panolan; M. S. Ramanujan; Saket Saurabh; Kirill Simonov',year=2025,url='https://doi.org/10.1145/3765285',pdf_url='https://fedorvf.github.io/articles/2025/2025f.pdf',locator='Published 7 October 2025, ACM Transactions on Algorithms 22(1), article 8. Introduction and Section 1.2: Min-Sum Disjoint Paths remains open already for k=3.'),dict(id='grid2024',title='Shortest Disjoint Paths on a Grid',authors='Mathieu Mari; Anish Mukherjee; Michał Pilipczuk; Piotr Sankowski',year=2024,url='https://doi.org/10.1137/1.9781611977912.14',locator='SODA 2024, pp. 346–365; publisher abstract checked for the infinite rectangular-grid restriction.'),dict(id='planar2025',title='Planar Disjoint Shortest Paths is Fixed-Parameter Tractable',authors='Michał Pilipczuk; Giannos Stamoulis; Michał Włodarczyk',year=2025,url='https://arxiv.org/abs/2505.03353',locator='Preprint v1, 6 May 2025; abstract explicitly requires each path to be shortest for its own terminal pair, rather than minimizing arbitrary total length.')])
save(i,dict(title='Polynomial-time minimum-total-length disjoint paths for fixed k',formal='For every fixed integer k≥3, is there a polynomial-time algorithm that, given an undirected unweighted graph G and k prescribed terminal pairs (sᵢ,tᵢ), outputs pairwise vertex-disjoint paths Pᵢ from sᵢ to tᵢ minimizing ∑ᵢ|E(Pᵢ)|, or correctly reports that no such collection exists? Randomized algorithms with success probability at least 2/3 on every input are admitted in this reading, consistently with the randomized k=2 baseline cited by the source. Polynomial degree and constants may depend on k; an FPT bound with exponent independent of k is not requested.',definitions='G is a finite simple connected undirected graph with n numbered vertices and unit length on every edge, encoded by an adjacency matrix and the terminal labels. Take the 2k terminals to be distinct; repeated endpoints across different pairs make vertex-disjointness infeasible, and a pair with sᵢ=tᵢ uses the zero-edge path at that vertex and can be handled separately. A path is a sequence of distinct vertices with consecutive vertices adjacent. Vertex-disjointness includes endpoints and means V(Pᵢ)∩V(Pⱼ)=∅ for i≠j. Pairings are fixed: connecting a source to a different pair’s target is not acceptable. Define OPT as the minimum sum of edge counts over all feasible collections and set OPT=∞ when there is none. The output consists of the k vertex sequences of an optimal collection, or an infeasibility answer. For each fixed k the algorithm is a probabilistic Turing machine, with one finite program handling all n and all inputs for that k, running in at most C_k(n+1)^{c_k} steps on every random-bit sequence. Constants C_k,c_k are independent of n. With probability at least 2/3 over its independent fair bits, the full output must be correct, including exact optimality. A deterministic algorithm is included as the zero-error case. The formulation asks for polynomial time for each fixed k and does not demand a uniform procedure generating these programs as k varies. The source compares this target with k-DSP, which requires every Pᵢ separately to have length dist_G(sᵢ,tᵢ). Such a collection, when it exists, has the smallest possible total length; minimum-total-length routing must also handle inputs where disjoint routes exist but no collection of individually shortest routes exists.',question_type='yes_no',answer_criterion='Establish or refute polynomial-time solvability, with the stated bounded-error allowance, for every fixed k≥3. A positive answer must output an exactly optimal collection or detect infeasibility on all inputs. A conditional negative answer must state its assumption and imply that no such polynomial-time algorithm exists for at least one fixed k. Hardness only when k grows with n, an FPT lower bound, approximation, or an algorithm restricted to individually shortest paths does not decide this question.',context_blocks=[dict(title='The objective permits necessary detours',text='Disjointness can force one route away from its own shortest path. The optimization problem allows such detours and asks for the smallest total number of edges over all routes. An algorithm checking only whether all individual shortest distances can be attained cannot handle the remaining instances.',citation='primary'),dict(title='Fixed k is the relevant complexity boundary',text='The source gives polynomial-time algorithms for individually shortest paths at every fixed k and cites a randomized polynomial-time algorithm for minimum total length when k=2. It leaves the minimum-total-length extension open for k≥3.',citation='primary'),dict(title='A specialized optimization result',text='The 2024 grid result handles minimum-total-length routing on an infinite rectangular grid. Its geometric restriction does not give the requested algorithm on arbitrary undirected graphs.',citation='grid2024'),dict(title='Planar shortest paths have a different objective',text='The 2025 planar preprint requires every route to be individually shortest. That condition does not handle general minimum-total-length routing when disjointness forces detours.',citation='planar2025'),dict(title='A recent source confirms the unresolved case',text='The published 2025 cycle-packing paper explicitly states that Min-Sum Disjoint Paths remains open even for three pairs on planar graphs. Its own polynomial-time result packs cycles without prescribed terminal pairs, so it does not settle this routing problem.',citation='cycles2025')],why='Would determine whether exact length optimization preserves the polynomial-time solvability of undirected disjoint routing with a fixed number of prescribed terminal pairs.',references=refs,progress=[dict(date='2021',text='The source improves fixed-k algorithms for individually shortest disjoint paths and leaves minimum-total-length routing open for k≥3.',citation='primary'),dict(date='2024',text='Minimum-total-length routing is shown FPT in the special setting of an infinite rectangular grid.',citation='grid2024'),dict(date='2025-10-07',text='The cycle-packing paper still lists the three-pair minimum-total-length routing problem as open, including on planar graphs.',citation='cycles2025')],status='source_open',status_note='Checked the original graph model and concluding question, the full 2025 cycle-packing discussion, and the exact scopes of the 2024 grid and 2025 planar results. Searches through 12 September 2026 identified no general fixed-k polynomial-time algorithm. Randomized bounded-error solvability is explicitly admitted as in the source’s k=2 comparison.',model_self_contained=True,requires_context=False,importance=dict(score=c['importance']['score'],method='editorial',reason='A basic unresolved gap between feasibility and exact optimization for a fixed number of disjoint routes. Existing score retained.',assessed_on=DATE),review_note='Restored the fixed-k, undirected unit-length optimization target. Defined exact output, vertex-disjointness, infeasibility, randomness and per-fixed-k running time. Separated total-length optimization from individually shortest paths and special graph classes.',working_summary=dict(sentences=['The graph is undirected and unweighted, with a fixed number k of prescribed terminal pairs.','The task is to find vertex-disjoint routes with the smallest possible total number of edges, or report that routing is impossible.','Individual routes may need to be longer than their own shortest paths to avoid the others.','The source asks for polynomial time at every fixed k≥3, allowing the exponent to depend on k.','Recent grid and individually-shortest-path results do not settle the general problem, which a 2025 published paper still lists as open for three pairs.'],basis='saved_sources',source_basis='source-text',written_on=DATE,source_refs=['primary','cycles2025','grid2024','planar2025'])),notes=['Recovered minimum total length rather than simultaneous individual shortestness.','Specified fixed-k quantifiers, unit edge lengths, terminal pairing and exact path output.','Documented the bounded-error interpretation of polynomial time using the source’s randomized baseline.','Checked the 2025 open-status statement and later specialized results.'],checked_sources=[r['url'] for r in refs])

i='TCS-3275';_,c=card(i);refs=c['references'];refs[0]['locator']='Conjecture 6, p. 4:4; Definition 9 and Remark 10, pp. 4:5–4:6; Theorem 5, p. 4:3 (soundness-only reduction).'
refs.extend([dict(id='ma2025',title='StoqMA vs. MA: the power of error reduction',authors='Dorit Aharonov; Alex B. Grilo; Yupan Liu',year=2025,url='https://doi.org/10.22331/q-2025-09-11-1853',pdf_url='https://quantum-journal.org/papers/q-2025-09-11-1853/pdf/',locator='Quantum 9, 1853, published 11 September 2025; arXiv:2010.02835v4, revised 4 September 2025. Conjecture 1.1 and Corollaries 1.4–1.5.'),dict(id='multi2026',title='The power of unentanglement without destructive interference',authors='Yupan Liu; Pei Wu',year=2026,url='https://arxiv.org/abs/2604.27886',pdf_url='https://arxiv.org/pdf/2604.27886v2',locator='Version 2, 12 July 2026; Section 1.2.4, immediately before Theorem 1.10, still states that general StoqMA error reduction is open. Partial repetition results concern restricted completeness regimes.'),dict(id='collapse2026',title='The Collapse of Unentangled Stoquastic Merlin-Arthur Proof Systems',authors='William Gay; Fernando Granha Jeronimo',year=2026,url='https://arxiv.org/abs/2605.16249',pdf_url='https://arxiv.org/pdf/2605.16249v1',locator='Preprint v1, 15 May 2026; Introduction and Remark 2.2 explicitly preserve inverse-polynomial gaps without using a general amplification theorem. Its claimed prover collapse is not full error reduction.')])
save(i,dict(title='Can StoqMA amplify both completeness and soundness?',formal='For every pair of efficiently computable threshold functions a(n),b(n) with 1/2≤b(n)<a(n)≤1 and a(n)−b(n)≥1/q(n) for some polynomial q, and every integer-valued polynomial ℓ(n)≥2, is StoqMA(a,b) contained in StoqMA(1−2^{−ℓ(n)}, 1/2+2^{−ℓ(n)})? Here n is the classical input length. The new verifier must remain in the same one-witness stoquastic circuit model, with polynomially many gates, witness qubits and ancillas.',definitions='A promise problem is a pair (L_yes,L_no) of disjoint sets of finite binary strings, with no required answer outside their union. Membership in StoqMA(a,b) means there is a deterministic polynomial-time procedure which, given x of length n, produces a verification circuit V_x on m(n)+r(n)+s(n) qubits, all counts polynomially bounded in n. Its initial state is |w⟩⊗|0⟩^{⊗r}⊗|+⟩^{⊗s}, where |+⟩=(|0⟩+|1⟩)/√2 and the m-qubit witness has norm one. The circuit uses only classical reversible gates: NOT flips a bit, CNOT flips its target if its control is one, and Toffoli flips its target if both controls are one. These gates act linearly on computational-basis states. There are no intermediate measurements or arbitrary quantum gates. At the end a designated output qubit is measured in the {|+⟩,|−⟩} basis, with |−⟩=(|0⟩−|1⟩)/√2, and outcome + means acceptance. Its acceptance probability is the squared norm after projection onto |+⟩ on that qubit. If x∈L_yes, some witness with real nonnegative computational-basis amplitudes must be accepted with probability at least a(n). If x∈L_no, every normalized witness, including arbitrary complex amplitudes, must be accepted with probability at most b(n). The source proves that a maximizing witness can be chosen nonnegative. Efficient threshold computability is understood in the standard precision sense: their values can be approximated within 2^{−t} in time polynomial in n+t. The inverse-polynomial gap permits this conventional representation. Class containment quantifies over promise problems and asserts existence of new uniform verifiers; it does not demand a blackbox compiler acting on an arbitrary verifier description. Polynomial bounds of the new verifier may depend on the original verifier, q and ℓ. Soundness approaches 1/2 from above, not zero; the requested improvement is relative to the stoquastic acceptance baseline.',question_type='yes_no',answer_criterion='Prove the containment for every admissible a,b and ℓ, or refute this universally quantified amplification statement. A positive answer must achieve both exponentially small completeness error and exponentially small excess soundness above 1/2 while retaining the allowed gates, initial ancillas and final measurement. Soundness-only repetition, perfect-completeness special cases, extra destructive-interference gates, or additional unentangled provers do not establish the claim.',context_blocks=[dict(title='The verifier has a restricted way to accept',text='The computation is classically reversible, but its ancillas and final measurement allow a nonnegative quantum witness to affect acceptance. This restricted verification model arises in the complexity of stoquastic local Hamiltonians. Familiar error-reduction statements for unrestricted quantum verification do not automatically give the required stoquastic verifier.',citation='primary'),dict(title='Soundness reduction alone is known',text='The source’s Theorem 5 maps thresholds (1/2+u/2,1/2+v/2) to (1/2+u^r/2,1/2+v^r/2) for polynomial r. This improves excess soundness but can also lower completeness. Conjecture 6 asks for simultaneous amplification towards completeness one and soundness one half.',citation='primary'),dict(title='Amplification would identify StoqMA with MA',text='The 2025 published paper proves that negligible completeness error with a suitable inverse-polynomial gap is already contained in MA, the class of promise problems verified in polynomial time with a classical witness and random bits. Its Corollary 1.5 makes general StoqMA error reduction equivalent to StoqMA=MA.',citation='ma2025'),dict(title='Recent multiwitness work keeps the question open',text='The July 2026 preprint still explicitly calls general one-witness error reduction open. Its restricted repetition results do not supply the two threshold limits required here for arbitrary original completeness.',citation='multi2026'),dict(title='Prover collapse is a separate claim',text='The May 2026 preprint claims that the number of stoquastic provers can be reduced while retaining an inverse-polynomial gap. It explicitly avoids assuming general amplification. This preprint claim is not recorded as a solution of the one-witness error-reduction question.',citation='collapse2026')],why='Would determine whether the stoquastic verification model has ordinary exponential error reduction and, through the published equivalence, whether its proof power collapses to classical Merlin–Arthur verification.',references=refs,progress=[dict(date='2021',text='Soundness-only error reduction is established, while Conjecture 6 states the simultaneous completeness/soundness target.',citation='primary'),dict(date='2025-09-11',text='A published theorem establishes that general StoqMA error reduction is equivalent to StoqMA=MA.',citation='ma2025'),dict(date='2026-07-12',text='A revised preprint on unentangled stoquastic proofs retains the general error-reduction problem as open and studies more restricted amplification guarantees.',citation='multi2026')],status='source_open',status_note='Read Conjecture 6, the verifier definition and soundness-only theorem, the 2025 published equivalence, and the relevant statements in the May and July 2026 preprints. No full one-witness amplification theorem was found through 12 September 2026. The July 2026 source explicitly still calls the general question open.',model_self_contained=True,requires_context=False,importance=dict(score=c['importance']['score'],method='editorial',reason='A foundational robustness question for stoquastic proofs, equivalent to a central equality between quantum-inspired and classical verification classes. Existing score retained.',assessed_on=DATE),review_note='Replaced the generic amplification fragment with Conjecture 6’s exact thresholds and quantifiers. Defined the witness, gates, ancillas, measurement, uniformity and error convention. Added the published MA equivalence and checked recent multiwitness work.',working_summary=dict(sentences=['A StoqMA verifier uses classical reversible gates, special initial ancillas and one final measurement in the plus/minus basis.','It accepts a suitable nonnegative quantum witness on yes instances and must reject arbitrary witnesses with the prescribed soundness bound on no instances.','The question asks whether every inverse-polynomial gap can be amplified to completeness exponentially close to one and soundness exponentially close to one half.','Soundness-only repetition is known, but it does not provide this simultaneous improvement.','A published theorem makes full error reduction equivalent to StoqMA=MA, and July 2026 work still states the general problem as open.'],basis='saved_sources',source_basis='source-text',written_on=DATE,source_refs=['primary','ma2025','multi2026','collapse2026'])),notes=['Recovered Conjecture 6’s exact containment and the soundness baseline 1/2.','Defined the uniform verifier, quantum witness quantifiers, reversible gates and final measurement.','Distinguished class containment from a stronger blackbox verifier-transformation demand.','Checked the published equivalence with MA and the restricted scope of 2026 preprints.'],checked_sources=[r['url'] for r in refs]+['https://arxiv.org/abs/2010.02835'])
